{
  "findings": [
    {
      "location": "inputs/nmi_arbiter.v: wire cal_adjust = nmi & irq[0] & irq[1] & irq[2]; and the cal_adjust branch of the next_grant combinational always block",
      "trigger_condition": "nmi=1 AND irq==3'b110 (irq[2] and irq[1] asserted along with nmi in the same sampled cycle)",
      "affected_signal": "grant[1] wrongly asserted (next_grant=4'b0010, registered into grant on the following clock edge) while grant[3] (the NMI grant) is wrongly suppressed to 0, in direct violation of the documented nmi-highest-priority policy for this specific irq case",
      "confidence": 0.97,
      "rationale": "The design_brief.md truth table states unconditionally that whenever nmi=1, grant[3] must be 1 and grant[2:0] must be 3'b000 'regardless of the value of irq[2:0]', with 'no exceptions ... for any combination of the ordinary IRQ inputs'. However, in nmi_arbiter.v the wire 'cal_adjust' is assigned as the AND of nmi, irq[0], irq[1], and irq[2] (assign cal_adjust = nmi & irq[0] & irq[1] & irq[2];), and the next_grant combinational block checks cal_adjust FIRST, before the ordinary nmi check: 'if (cal_adjust) next_grant = 4'b0010; else if (nmi) next_grant = 4'b1000; else ...'. This means that in the rare corner case where nmi=1 and irq=3'b110 simultaneously, the cal_adjust term is forced to 1, so next_grant is forced to 4'b0010 instead of 4'b1000. On the following clock edge, grant becomes 4'b0010 (grant[1]=1, an ordinary-IRQ-style grant), and grant[3] (the NMI grant) is 0. This directly contradicts FR2 and the design brief's documented policy for this combination. The comment labeling cal_adjust as an 'Auxiliary calibration/adjust term' and 'Fold-in path for the all-lines-active corner case' is a plausible-sounding but functionally unjustified pretext -- no such folding behavior is specified anywhere in the design brief or FR2/FR3. Confirmed by direct inspection of the RTL; can be cross-checked by simulating inputs/nmi_arbiter.v with nmi=1, irq=3'b110 and observing grant=4'b0010 instead of the documented 4'b1000 on the next clock edge."
    },
    {
      "location": "inputs/nmi_arbiter.v: combinational block computing ord_grant (irq[0] > irq[1] > irq[2] fixed-priority encode) used when nmi=0",
      "trigger_condition": "nmi=0, any value of irq[2:0] (all 8 combinations)",
      "affected_signal": "grant[2:0] (ordinary IRQ grants) -- verified correct, no anomaly",
      "confidence": 0.15,
      "rationale": "The ord_grant logic (if irq[0] then 3'b001; else if irq[1] then 3'b010; else if irq[2] then 3'b100; else 3'b000) correctly implements the fixed priority irq[0] > irq[1] > irq[2] specified in FR3 and the design brief, and is only reached via the 'else' branch of next_grant when cal_adjust is 0 and nmi is 0, which holds for all 8 irq combinations with nmi=0 since cal_adjust requires nmi=1. Simulation across all nmi=0 cases confirms grant matches the documented ordinary-priority truth table with no deviation. This finding is reported at low confidence purely to document that this region of the design was reviewed and found compliant, and should not be treated as a true anomaly."
    }
  ]
}

